-- 200: Original BrillaPrep WASSCE BrillaPrep transitional Basketry beta content blueprint questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_200_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_200_guard;
INSERT INTO _migration_200_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_029' AND NOT (q.topic_id IS 'topic_was_basketry_b004_6' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a carrying handle be anchored through several sound structural elements?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fasten each handle end to a single thick stake selected mainly for its diameter","B. Loop each end around the rim braid at opposite points because the border already spans the opening","C. The load is distributed instead of concentrating at one weak strand","D. Stitch each end through several nearby decorative weavers without engaging the main stakes"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Spreading the connection through stakes, rim members or reinforced areas lowers local stress and reduces the chance of pull-out when the loaded basket is lifted repeatedly. Therefore the correct answer is C: The load is distributed instead of concentrating at one weak strand.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_029' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_200_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_030' AND NOT (q.topic_id IS 'topic_was_basketry_b004_6' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which working sequence produces a basic over-two-under-two twill weave in basketry?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Pass each weaver over two stakes and under two, offsetting the next row to develop a diagonal progression","B. Pass one weaver over one stake and under one, continuing the same alternation around the basket","C. Work three weavers in sequence around the stakes so each course forms a firm horizontal band","D. Twist two weavers around successive stakes and leave measured open spaces between the woven rows"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A basic twill groups crossings over two and under two and offsets successive rows, so the visible floats advance diagonally. The alternatives describe simple randing, open fitching and a multi-weaver strengthening course. Therefore the correct answer is A: Pass each weaver over two stakes and under two, offsetting the next row to develop a diagonal progression.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_030' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_200_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_031' AND NOT (q.topic_id IS 'topic_was_basketry_b004_7' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement correctly distinguishes an illustration from a sketch in basketry design development?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A sketch quickly explores an idea with limited detail, while an illustration develops form through clearer drawing, detail and shading","B. Sketch and illustration are interchangeable whenever both show the basket from a single viewpoint","C. A sketch is the polished presentation image, while an illustration is an unrefined outline made before options are explored","D. A sketch is the final measured construction drawing, while an illustration is the first loose record of an idea"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A sketch captures and tests an idea rapidly, often with few details. An illustration communicates the intended basket more fully through developed drawing, visible details and shading, so it can explain form more clearly to another viewer. Therefore the correct answer is A: A sketch quickly explores an idea with limited detail, while an illustration develops form through clearer drawing, detail and shading.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_031' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_200_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_basketry_b004_032' AND NOT (q.topic_id IS 'topic_was_basketry_b004_7' AND q.subject_id IS 'subj_wassce_basketry' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which expense is most appropriately treated as workshop overhead rather than direct material for one basket?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The cane lengths measured and woven into that basket","B. The dye quantity recorded specifically for that basket","C. A fair share of workshop lighting and rent","D. The handle fittings permanently attached to that basket"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Lighting and rent support several products and cannot normally be traced economically to one unit, so a consistent allocation method includes their share in total production cost. Therefore the correct answer is C: A fair share of workshop lighting and rent.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_basketry_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_basketry_b004_032' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_029', 'topic_was_basketry_b004_6', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Why should a carrying handle be anchored through several sound structural elements?', 'multiple_choice', NULL, '["A. Fasten each handle end to a single thick stake selected mainly for its diameter","B. Loop each end around the rim braid at opposite points because the border already spans the opening","C. The load is distributed instead of concentrating at one weak strand","D. Stitch each end through several nearby decorative weavers without engaging the main stakes"]', 'C', 'Spreading the connection through stakes, rim members or reinforced areas lowers local stress and reduces the chance of pull-out when the loaded basket is lifted repeatedly. Therefore the correct answer is C: The load is distributed instead of concentrating at one weak strand.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_6', 'Explain', 'AO2', NULL, NULL, 'board_waec');
