INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_031', 'topic_was_basketry_b004_7', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which statement correctly distinguishes an illustration from a sketch in basketry design development?', 'multiple_choice', NULL, '["A. A sketch quickly explores an idea with limited detail, while an illustration develops form through clearer drawing, detail and shading","B. Sketch and illustration are interchangeable whenever both show the basket from a single viewpoint","C. A sketch is the polished presentation image, while an illustration is an unrefined outline made before options are explored","D. A sketch is the final measured construction drawing, while an illustration is the first loose record of an idea"]', 'A', 'A sketch captures and tests an idea rapidly, often with few details. An illustration communicates the intended basket more fully through developed drawing, visible details and shading, so it can explain form more clearly to another viewer. Therefore the correct answer is A: A sketch quickly explores an idea with limited detail, while an illustration develops form through clearer drawing, detail and shading.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_7', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_basketry_b004_032', 'topic_was_basketry_b004_7', 'subj_wassce_basketry', 'exam_wassce', NULL, NULL, 'Which expense is most appropriately treated as workshop overhead rather than direct material for one basket?', 'multiple_choice', NULL, '["A. The cane lengths measured and woven into that basket","B. The dye quantity recorded specifically for that basket","C. A fair share of workshop lighting and rent","D. The handle fittings permanently attached to that basket"]', 'C', 'Lighting and rent support several products and cannot normally be traced economically to one unit, so a consistent allocation method includes their share in total production cost. Therefore the correct answer is C: A fair share of workshop lighting and rent.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_basketry_b004_7', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Basketry practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_basketry_b004_029', 'q_was_basketry_b004_030', 'q_was_basketry_b004_031', 'q_was_basketry_b004_032');
